#!/usr/bin/env ruby
require'json';require'find';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);development=File.join(client,'development');archives=Dir.glob(File.join(development,'archived-*'))+[File.join(development,'migration/aoo_DFMJ-3.8.8')];uuids=[];archives.each{|dir|Dir.glob(File.join(dir,'**/*.meta')).each{|p|begin;u=JSON.parse(File.read(p))['uuid'];uuids<<u if u;rescue;end}};path_patterns=archives.map{|p|File.basename(p)};hits=[];Find.find(File.join(client,'assets')) do|p|next unless File.file?(p);next if File.size(p)>10_000_000;t=File.binread(p).force_encoding('UTF-8').scrub;matched=uuids.select{|u|t.include?(u)}+path_patterns.select{|v|t.include?(v)};hits<<{file:p.delete_prefix(client+'/'),references:matched.uniq}unless matched.empty?;end;checks={noArchivedUuidReferences:hits.none?{|h|(h[:references]&uuids).any?},noArchivedPathReferences:hits.none?{|h|(h[:references]&path_patterns).any?},archivesOutsideAssets:archives.all?{|p|!p.start_with?(File.join(client,'assets'))}};report={schemaVersion:1,archiveRoots:archives.map{|p|p.delete_prefix(client+'/')},archiveUuids:uuids.length,hits:hits,checks:checks};out=File.join(root,'docs/generated/carch08-dynamic-archive-references.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort("CARCH08 failed: #{checks}")unless checks.values.all?;puts 'CARCH08 PASS: no active string, UUID or bundle reference reaches archives'
